-- ----------------------------------------------------------------------------
-- RulebookDomains: Customer ontologies: each domain has its own rulebook + substrate generation. Domains form a TREE — ParentDomainId links a more-elaborate domain back to the simpler one it grew out of (e.g. Talisman ADVANCED ← Talisman BASIC). The UI uses this to present related rulebooks as a set rather than a flat list, and to drive 'next step in the progression' navigation.
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS rulebook_domains (
  domain_id                           TEXT                 PRIMARY KEY
);
ALTER TABLE rulebook_domains ADD COLUMN IF NOT EXISTS area TEXT;                                    -- Witnessed physical container: root, rulebook-examples, or toy-rulebooks. Classification is derived separately.
ALTER TABLE rulebook_domains ADD COLUMN IF NOT EXISTS kind TEXT;                                    -- Declared classification: root | toy | example. A toy is a statement of intent (a small teaching rulebook), not a count of files; change this value to re-classify a project. The folder it lives in is witnessed separately as Area.
ALTER TABLE rulebook_domains ADD COLUMN IF NOT EXISTS is_intentional_exception BOOLEAN;             -- True only for the two doctrine-sanctioned containers that deliberately carry no rulebook (naked-claude-vs-effortless-claude, volunteer-shift-scheduler-demo).
ALTER TABLE rulebook_domains ADD COLUMN IF NOT EXISTS domain_name TEXT;
ALTER TABLE rulebook_domains ADD COLUMN IF NOT EXISTS relative_path TEXT;                           -- rulebook-examples/{domain}/ — each domain is a self-contained Effortless project
ALTER TABLE rulebook_domains ADD COLUMN IF NOT EXISTS rulebook_path TEXT;                           -- Path to effortless-rulebook.json within domain
ALTER TABLE rulebook_domains ADD COLUMN IF NOT EXISTS complexity_level TEXT;                        -- minimal, moderate, advanced, or philosophical
ALTER TABLE rulebook_domains ADD COLUMN IF NOT EXISTS table_count NUMERIC;
ALTER TABLE rulebook_domains ADD COLUMN IF NOT EXISTS key_features TEXT;                            -- Comma-separated: string concat, relationships, aggregations, IF logic, meta-ontology, etc.
ALTER TABLE rulebook_domains ADD COLUMN IF NOT EXISTS purpose TEXT;
ALTER TABLE rulebook_domains ADD COLUMN IF NOT EXISTS parent_domain_id TEXT;                        -- FK to RulebookDomains.DomainId — the simpler domain this one was derived from / builds on. Null for root-level demos (independent starting points). Lets the UI present rulebooks as a tree of related domains.
ALTER TABLE rulebook_domains ADD COLUMN IF NOT EXISTS progression_note TEXT;                        -- One sentence describing what this domain ADDS over its parent — the specific concept the progression is meant to demonstrate at this step.
ALTER TABLE rulebook_domains ADD COLUMN IF NOT EXISTS project TEXT;                                 -- FK to ProjectMetadata — roots this catalog row to the platform row so repo-wide rollups exist on one dashboard record.
COMMENT ON TABLE rulebook_domains IS 'Customer ontologies: each domain has its own rulebook + substrate generation. Domains form a TREE — ParentDomainId links a more-elaborate domain back to the simpler one it grew out of (e.g. Talisman ADVANCED ← Talisman BASIC). The UI uses this to present related rulebooks as a set rather than a flat list, and to drive ''next step in the progression'' navigation.';
COMMENT ON COLUMN rulebook_domains.area IS 'Witnessed physical container: root, rulebook-examples, or toy-rulebooks. Classification is derived separately.';
COMMENT ON COLUMN rulebook_domains.kind IS 'Declared classification: root | toy | example. A toy is a statement of intent (a small teaching rulebook), not a count of files; change this value to re-classify a project. The folder it lives in is witnessed separately as Area.';
COMMENT ON COLUMN rulebook_domains.is_intentional_exception IS 'True only for the two doctrine-sanctioned containers that deliberately carry no rulebook (naked-claude-vs-effortless-claude, volunteer-shift-scheduler-demo).';
COMMENT ON COLUMN rulebook_domains.relative_path IS 'rulebook-examples/{domain}/ — each domain is a self-contained Effortless project';
COMMENT ON COLUMN rulebook_domains.rulebook_path IS 'Path to effortless-rulebook.json within domain';
COMMENT ON COLUMN rulebook_domains.complexity_level IS 'minimal, moderate, advanced, or philosophical';
COMMENT ON COLUMN rulebook_domains.key_features IS 'Comma-separated: string concat, relationships, aggregations, IF logic, meta-ontology, etc.';
COMMENT ON COLUMN rulebook_domains.parent_domain_id IS 'FK to RulebookDomains.DomainId — the simpler domain this one was derived from / builds on. Null for root-level demos (independent starting points). Lets the UI present rulebooks as a tree of related domains.';
COMMENT ON COLUMN rulebook_domains.progression_note IS 'One sentence describing what this domain ADDS over its parent — the specific concept the progression is meant to demonstrate at this step.';
COMMENT ON COLUMN rulebook_domains.project IS 'FK to ProjectMetadata — roots this catalog row to the platform row so repo-wide rollups exist on one dashboard record.';

