ALTER TABLE execution_substrates ADD COLUMN IF NOT EXISTS transpiler_source TEXT;                   -- licensed-effortless-tool | local-injector | external. WHO BUILT THE GENERATOR — provenance, not trustworthiness. Replaces the old IsProduction column. See FramingInvariants.framing-003.
ALTER TABLE execution_substrates ADD COLUMN IF NOT EXISTS maturity TEXT;                            -- prototype | demonstrating | reference-quality — how complete THIS substrate's implementation is. Independent of TranspilerSource.
ALTER TABLE execution_substrates ADD COLUMN IF NOT EXISTS expressive_completeness TEXT;             -- full | partial-aggregation | partial-formula | shape-only — which formula classes this substrate can faithfully evaluate. A factual property of the substrate engine.
ALTER TABLE execution_substrates ADD COLUMN IF NOT EXISTS can_be_answer_key BOOLEAN;                -- Can serve as the oracle (SSoT) in a conformance run if the user designates it. True for any substrate whose output is fully witnessable. NOT an authority ranking — see ax-002.
ALTER TABLE execution_substrates ADD COLUMN IF NOT EXISTS determinism TEXT;                         -- deterministic | stochastic | externally-influenced — pure-function reproducibility class of the substrate
ALTER TABLE execution_substrates ADD COLUMN IF NOT EXISTS runtime_kind TEXT;                        -- database | spreadsheet | binary | text-emit | graph | docs — what kind of artifact this substrate produces / runs as
ALTER TABLE execution_substrates ADD COLUMN IF NOT EXISTS status TEXT;                              -- Operational status (active, proof-of-concept, deprecated). Lifecycle, not trustworthiness.
ALTER TABLE execution_substrates ADD COLUMN IF NOT EXISTS description TEXT;                         -- Purpose and capabilities
ALTER TABLE execution_substrates ADD COLUMN IF NOT EXISTS project TEXT;                             -- FK to ProjectMetadata — roots this catalog row to the platform row so repo-wide rollups exist on one dashboard record.
COMMENT ON TABLE execution_substrates IS 'Runtime environments that execute business rules derived from the rulebook';
COMMENT ON COLUMN execution_substrates.name IS 'Human-readable substrate name';
COMMENT ON COLUMN execution_substrates.technology IS 'Language/platform (PostgreSQL, Python, Go, Excel, OWL, PlantUML, etc.)';
COMMENT ON COLUMN execution_substrates.relative_path IS 'Path within repo: execution-substrates/{technology}/';
COMMENT ON COLUMN execution_substrates.injector_script IS 'Code generation script: inject-into-{technology}.py';
COMMENT ON COLUMN execution_substrates.test_script IS 'Conformance test script: take-test.py';
COMMENT ON COLUMN execution_substrates.transpiler_source IS 'licensed-effortless-tool | local-injector | external. WHO BUILT THE GENERATOR — provenance, not trustworthiness. Replaces the old IsProduction column. See FramingInvariants.framing-003.';
COMMENT ON COLUMN execution_substrates.maturity IS 'prototype | demonstrating | reference-quality — how complete THIS substrate''s implementation is. Independent of TranspilerSource.';
COMMENT ON COLUMN execution_substrates.expressive_completeness IS 'full | partial-aggregation | partial-formula | shape-only — which formula classes this substrate can faithfully evaluate. A factual property of the substrate engine.';
COMMENT ON COLUMN execution_substrates.can_be_answer_key IS 'Can serve as the oracle (SSoT) in a conformance run if the user designates it. True for any substrate whose output is fully witnessable. NOT an authority ranking — see ax-002.';
COMMENT ON COLUMN execution_substrates.determinism IS 'deterministic | stochastic | externally-influenced — pure-function reproducibility class of the substrate';
COMMENT ON COLUMN execution_substrates.runtime_kind IS 'database | spreadsheet | binary | text-emit | graph | docs — what kind of artifact this substrate produces / runs as';
COMMENT ON COLUMN execution_substrates.status IS 'Operational status (active, proof-of-concept, deprecated). Lifecycle, not trustworthiness.';
COMMENT ON COLUMN execution_substrates.description IS 'Purpose and capabilities';
COMMENT ON COLUMN execution_substrates.project IS 'FK to ProjectMetadata — roots this catalog row to the platform row so repo-wide rollups exist on one dashboard record.';

