-- calc_ontology_axioms_name
-- Field: OntologyAxioms.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_ontology_axioms_name(p_axiom_id TEXT)
RETURNS TEXT AS $$
  SELECT ((SELECT NULLIF(short_name, '') FROM ontology_axioms WHERE axiom_id = p_axiom_id))::text;
$$ LANGUAGE sql STABLE;

-- calc_ontology_axioms_invariant_count
-- Field: OntologyAxioms.InvariantCount
-- Type: aggregation | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_ontology_axioms_invariant_count(p_axiom_id TEXT)
RETURNS NUMERIC AS $$
  SELECT ((SELECT COUNT(*) FROM framing_invariants WHERE violated_axiom_id = (SELECT NULLIF(axiom_id, '') FROM ontology_axioms WHERE axiom_id = p_axiom_id)))::numeric;
$$ LANGUAGE sql STABLE;

-- calc_ontology_axioms_feature_count
-- Field: OntologyAxioms.FeatureCount
-- Type: aggregation | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_ontology_axioms_feature_count(p_axiom_id TEXT)
RETURNS NUMERIC AS $$
  SELECT ((SELECT COUNT(*) FROM platform_features WHERE related_axiom_id = (SELECT NULLIF(axiom_id, '') FROM ontology_axioms WHERE axiom_id = p_axiom_id)))::numeric;
$$ LANGUAGE sql STABLE;

-- calc_ontology_axioms_is_active
-- Field: OntologyAxioms.IsActive
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_ontology_axioms_is_active(p_axiom_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((SELECT NULLIF(status, '') FROM ontology_axioms WHERE axiom_id = p_axiom_id) = 'active')::boolean;
$$ LANGUAGE sql STABLE;

-- calc_ontology_axioms_critical_invariant_count
-- Field: OntologyAxioms.CriticalInvariantCount
-- Type: aggregation | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_ontology_axioms_critical_invariant_count(p_axiom_id TEXT)
RETURNS NUMERIC AS $$
  SELECT ((SELECT COALESCE(SUM((calc_framing_invariants_critical_flag(invariant_id))::numeric), 0) FROM framing_invariants WHERE violated_axiom_id = p_axiom_id))::numeric;
$$ LANGUAGE sql STABLE;

-- calc_ontology_axioms_shipped_feature_count
-- Field: OntologyAxioms.ShippedFeatureCount
-- Type: aggregation | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_ontology_axioms_shipped_feature_count(p_axiom_id TEXT)
RETURNS NUMERIC AS $$
  SELECT ((SELECT COALESCE(SUM((calc_platform_features_shipped_flag(feature_id))::numeric), 0) FROM platform_features WHERE related_axiom_id = p_axiom_id))::numeric;
$$ LANGUAGE sql STABLE;

-- calc_ontology_axioms_is_load_bearing
-- Field: OntologyAxioms.IsLoadBearing
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_ontology_axioms_is_load_bearing(p_axiom_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (((calc_ontology_axioms_invariant_count(p_axiom_id))::NUMERIC > 0 OR (calc_ontology_axioms_feature_count(p_axiom_id))::NUMERIC > 0));
$$ LANGUAGE sql STABLE;

-- calc_ontology_axioms_is_well_guarded
-- Field: OntologyAxioms.IsWellGuarded
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_ontology_axioms_is_well_guarded(p_axiom_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((calc_ontology_axioms_is_load_bearing(p_axiom_id) AND (calc_ontology_axioms_critical_invariant_count(p_axiom_id))::NUMERIC > 0));
$$ LANGUAGE sql STABLE;

-- calc_ontology_axioms_guard_ratio
-- Field: OntologyAxioms.GuardRatio
-- Type: calculated | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_ontology_axioms_guard_ratio(p_axiom_id TEXT)
RETURNS NUMERIC AS $$
  WITH __erb_dedup_v1 AS (SELECT calc_ontology_axioms_invariant_count(p_axiom_id) AS val) SELECT (CASE WHEN ((SELECT val FROM __erb_dedup_v1))::NUMERIC = 0 THEN (0)::text ELSE (ROUND(((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_ontology_axioms_critical_invariant_count(p_axiom_id)) AS v) __safe_numeric), 0) / NULLIF(COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT val FROM __erb_dedup_v1)) AS v) __safe_numeric), 0), 0)))::NUMERIC, (2)::INTEGER))::text END)::numeric;
$$ LANGUAGE sql STABLE;

-- calc_ontology_axioms_guard_state
-- Field: OntologyAxioms.GuardState
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_ontology_axioms_guard_state(p_axiom_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN calc_ontology_axioms_is_well_guarded(p_axiom_id) THEN ('guarded')::text ELSE (CASE WHEN calc_ontology_axioms_is_load_bearing(p_axiom_id) THEN ('exposed')::text ELSE ('dormant')::text END)::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_ontology_axioms_is_exposed_foundation
-- Field: OntologyAxioms.IsExposedFoundation
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_ontology_axioms_is_exposed_foundation(p_axiom_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (calc_ontology_axioms_guard_state(p_axiom_id) = 'exposed')::boolean;
$$ LANGUAGE sql STABLE;

-- calc_framing_invariants_axiom_short_name
-- Field: FramingInvariants.AxiomShortName
-- Type: lookup | DataType: string | Returns: TEXT
-- Lookup: ShortName from related OntologyAxioms


CREATE OR REPLACE FUNCTION calc_framing_invariants_axiom_short_name(p_invariant_id TEXT)
RETURNS TEXT AS $$
  SELECT (SELECT short_name::text FROM ontology_axioms WHERE axiom_id = (SELECT violated_axiom_id FROM framing_invariants WHERE invariant_id = p_invariant_id));
$$ LANGUAGE sql STABLE;

-- calc_framing_invariants_axiom_is_active
