CREATE OR REPLACE FUNCTION calc_framing_invariants_axiom_is_load_bearing(p_invariant_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT calc_ontology_axioms_is_load_bearing((SELECT violated_axiom_id FROM framing_invariants WHERE invariant_id = p_invariant_id));
$$ LANGUAGE sql STABLE;

