RETURNS TEXT AS $$
  SELECT (SELECT status FROM user_stories WHERE user_story_id = p_user_story_id);
$$ LANGUAGE sql STABLE;

-- get_user_stories_dev_progress_percent
-- Helper function: Get DevProgressPercent from UserStories by UserStoryId
-- Used for join-free cross-table references in aggregations

CREATE OR REPLACE FUNCTION get_user_stories_dev_progress_percent(p_user_story_id TEXT)
RETURNS NUMERIC AS $$
  SELECT (SELECT dev_progress_percent FROM user_stories WHERE user_story_id = p_user_story_id);
$$ LANGUAGE sql STABLE;

-- calc_build_phases_name
-- Field: BuildPhases.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_build_phases_name(p_build_phase_id TEXT)
RETURNS TEXT AS $$
  SELECT ((SELECT NULLIF(title, '') FROM build_phases WHERE build_phase_id = p_build_phase_id))::text;
$$ LANGUAGE sql STABLE;

-- calc_build_phases_story_count
-- Field: BuildPhases.StoryCount
-- Type: aggregation | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_build_phases_story_count(p_build_phase_id TEXT)
RETURNS NUMERIC AS $$
  SELECT ((SELECT COUNT(*) FROM user_stories WHERE build_phase = (SELECT NULLIF(build_phase_id, '') FROM build_phases WHERE build_phase_id = p_build_phase_id)))::numeric;
$$ LANGUAGE sql STABLE;

-- calc_build_phases_package_count
-- Field: BuildPhases.PackageCount
-- Type: aggregation | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_build_phases_package_count(p_build_phase_id TEXT)
RETURNS NUMERIC AS $$
  SELECT ((SELECT COUNT(*) FROM erb_packages WHERE primary_phase = (SELECT NULLIF(build_phase_id, '') FROM build_phases WHERE build_phase_id = p_build_phase_id)))::numeric;
$$ LANGUAGE sql STABLE;

-- calc_build_phases_is_priced
-- Field: BuildPhases.IsPriced
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_build_phases_is_priced(p_build_phase_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE((SELECT quoted_price FROM build_phases WHERE build_phase_id = p_build_phase_id), 0))::NUMERIC > 0)::boolean;
$$ LANGUAGE sql STABLE;

-- calc_build_phases_priced_flag
-- Field: BuildPhases.PricedFlag
-- Type: calculated | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_build_phases_priced_flag(p_build_phase_id TEXT)
RETURNS NUMERIC AS $$
  SELECT (CASE WHEN (COALESCE((SELECT quoted_price FROM build_phases WHERE build_phase_id = p_build_phase_id), 0))::NUMERIC > 0 THEN (1)::text ELSE (0)::text END)::numeric;
$$ LANGUAGE sql STABLE;

-- calc_build_phases_is_fixed_price
-- Field: BuildPhases.IsFixedPrice
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_build_phases_is_fixed_price(p_build_phase_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((SELECT NULLIF(phase_kind, '') FROM build_phases WHERE build_phase_id = p_build_phase_id) = 'fixed-price')::boolean;
$$ LANGUAGE sql STABLE;

-- calc_build_phases_done_story_count
-- Field: BuildPhases.DoneStoryCount
-- Type: aggregation | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_build_phases_done_story_count(p_build_phase_id TEXT)
RETURNS NUMERIC AS $$
  SELECT ((SELECT COALESCE(SUM((calc_user_stories_done_flag(user_story_id))::numeric), 0) FROM user_stories WHERE build_phase = p_build_phase_id))::numeric;
$$ LANGUAGE sql STABLE;

-- calc_build_phases_effort_weight_sum
-- Field: BuildPhases.EffortWeightSum
-- Type: aggregation | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_build_phases_effort_weight_sum(p_build_phase_id TEXT)
RETURNS NUMERIC AS $$
  SELECT ((SELECT COALESCE(SUM((calc_user_stories_effort_weight(user_story_id))::numeric), 0) FROM user_stories WHERE build_phase = p_build_phase_id))::numeric;
$$ LANGUAGE sql STABLE;

-- calc_build_phases_has_stories
-- Field: BuildPhases.HasStories
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_build_phases_has_stories(p_build_phase_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((calc_build_phases_story_count(p_build_phase_id))::NUMERIC > 0)::boolean;
$$ LANGUAGE sql STABLE;

-- calc_build_phases_done_percent
-- Field: BuildPhases.DonePercent
-- Type: calculated | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_build_phases_done_percent(p_build_phase_id TEXT)
RETURNS NUMERIC AS $$
  WITH __erb_dedup_v1 AS (SELECT calc_build_phases_story_count(p_build_phase_id) AS val) SELECT (CASE WHEN ((SELECT val FROM __erb_dedup_v1))::NUMERIC = 0 THEN (0)::text ELSE (ROUND(((COALESCE(100, 0) * COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_build_phases_done_story_count(p_build_phase_id)) AS v) __safe_numeric), 0) / NULLIF(COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT val FROM __erb_dedup_v1)) AS v) __safe_numeric), 0), 0))) AS v) __safe_numeric), 0)))::NUMERIC, (0)::INTEGER))::text END)::numeric;
$$ LANGUAGE sql STABLE;

-- calc_build_phases_weighted_done_sum
-- Field: BuildPhases.WeightedDoneSum
-- Type: aggregation | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_build_phases_weighted_done_sum(p_build_phase_id TEXT)
RETURNS NUMERIC AS $$
  SELECT ((SELECT COALESCE(SUM((calc_user_stories_weighted_done(user_story_id))::numeric), 0) FROM user_stories WHERE build_phase = p_build_phase_id))::numeric;
$$ LANGUAGE sql STABLE;

-- calc_build_phases_is_priced_with_stories
-- Field: BuildPhases.IsPricedWithStories
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_build_phases_is_priced_with_stories(p_build_phase_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((calc_build_phases_is_priced(p_build_phase_id) AND calc_build_phases_has_stories(p_build_phase_id)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_build_phases_weighted_done_percent
-- Field: BuildPhases.WeightedDonePercent
-- Type: calculated | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_build_phases_weighted_done_percent(p_build_phase_id TEXT)
RETURNS NUMERIC AS $$
  WITH __erb_dedup_v1 AS (SELECT calc_build_phases_effort_weight_sum(p_build_phase_id) AS val) SELECT (CASE WHEN ((SELECT val FROM __erb_dedup_v1))::NUMERIC = 0 THEN (0)::text ELSE (ROUND(((COALESCE(100, 0) * COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_build_phases_weighted_done_sum(p_build_phase_id)) AS v) __safe_numeric), 0) / NULLIF(COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT val FROM __erb_dedup_v1)) AS v) __safe_numeric), 0), 0))) AS v) __safe_numeric), 0)))::NUMERIC, (0)::INTEGER))::text END)::numeric;
$$ LANGUAGE sql STABLE;

-- calc_build_phases_avg_story_progress
-- Field: BuildPhases.AvgStoryProgress
-- Type: aggregation | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_build_phases_avg_story_progress(p_build_phase_id TEXT)
RETURNS NUMERIC AS $$
  SELECT ((SELECT COALESCE(AVG((calc_user_stories_derived_progress_percent(user_story_id))::numeric), 0) FROM user_stories WHERE build_phase = p_build_phase_id))::numeric;
$$ LANGUAGE sql STABLE;

-- calc_build_phases_is_contract_safe
-- Field: BuildPhases.IsContractSafe
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_build_phases_is_contract_safe(p_build_phase_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((NOT (calc_build_phases_is_priced(p_build_phase_id)) OR calc_build_phases_is_priced_with_stories(p_build_phase_id)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_build_phases_phase_state
-- Field: BuildPhases.PhaseState
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_build_phases_phase_state(p_build_phase_id TEXT)
RETURNS TEXT AS $$
  WITH __erb_dedup_v1 AS (SELECT calc_build_phases_weighted_done_percent(p_build_phase_id) AS val) SELECT (CASE WHEN ((SELECT val FROM __erb_dedup_v1))::NUMERIC = 100 THEN ('complete')::text ELSE (CASE WHEN ((SELECT val FROM __erb_dedup_v1))::NUMERIC > 0 THEN ('in-progress')::text ELSE (CASE WHEN COALESCE((SELECT is_current_bid FROM build_phases WHERE build_phase_id = p_build_phase_id), FALSE) THEN ('bid')::text ELSE ('planned')::text END)::text END)::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_build_phases_is_report_safe
-- Field: BuildPhases.IsReportSafe
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_build_phases_is_report_safe(p_build_phase_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((calc_build_phases_is_contract_safe(p_build_phase_id) AND calc_build_phases_has_stories(p_build_phase_id)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_effort_classes_name
-- Field: EffortClasses.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_effort_classes_name(p_effort_class_id TEXT)
RETURNS TEXT AS $$
  SELECT ((SELECT NULLIF(title, '') FROM effort_classes WHERE effort_class_id = p_effort_class_id))::text;
$$ LANGUAGE sql STABLE;

-- calc_effort_classes_story_count
-- Field: EffortClasses.StoryCount
-- Type: aggregation | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_effort_classes_story_count(p_effort_class_id TEXT)
RETURNS NUMERIC AS $$
  SELECT ((SELECT COUNT(*) FROM user_stories WHERE effort_class = (SELECT NULLIF(effort_class_id, '') FROM effort_classes WHERE effort_class_id = p_effort_class_id)))::numeric;
$$ LANGUAGE sql STABLE;

-- calc_effort_classes_weighted_story_load
-- Field: EffortClasses.WeightedStoryLoad
-- Type: calculated | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_effort_classes_weighted_story_load(p_effort_class_id TEXT)
RETURNS NUMERIC AS $$
  SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_effort_classes_story_count(p_effort_class_id)) AS v) __safe_numeric), 0) * COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT complexity_weight FROM effort_classes WHERE effort_class_id = p_effort_class_id)) AS v) __safe_numeric), 0)))::numeric;
$$ LANGUAGE sql STABLE;

-- calc_effort_classes_is_heavy_load
-- Field: EffortClasses.IsHeavyLoad
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_effort_classes_is_heavy_load(p_effort_class_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((calc_effort_classes_weighted_story_load(p_effort_class_id))::NUMERIC >= 20)::boolean;
$$ LANGUAGE sql STABLE;

-- calc_effort_classes_load_band
-- Field: EffortClasses.LoadBand
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_effort_classes_load_band(p_effort_class_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN calc_effort_classes_is_heavy_load(p_effort_class_id) THEN ('heavy')::text ELSE ('light')::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_effort_classes_class_label
-- Field: EffortClasses.ClassLabel
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_effort_classes_class_label(p_effort_class_id TEXT)
RETURNS TEXT AS $$
  SELECT (CONCAT((SELECT NULLIF(title, '') FROM effort_classes WHERE effort_class_id = p_effort_class_id), ' (', calc_effort_classes_load_band(p_effort_class_id), ')'))::text;
$$ LANGUAGE sql STABLE;

-- calc_delivery_disciplines_name
-- Field: DeliveryDisciplines.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_delivery_disciplines_name(p_delivery_discipline_id TEXT)
RETURNS TEXT AS $$
  SELECT ((SELECT NULLIF(title, '') FROM delivery_disciplines WHERE delivery_discipline_id = p_delivery_discipline_id))::text;
$$ LANGUAGE sql STABLE;

-- calc_delivery_disciplines_visible_share
-- Field: DeliveryDisciplines.VisibleShare
-- Type: calculated | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_delivery_disciplines_visible_share(p_delivery_discipline_id TEXT)
RETURNS NUMERIC AS $$
  SELECT (CASE WHEN COALESCE((SELECT client_visible FROM delivery_disciplines WHERE delivery_discipline_id = p_delivery_discipline_id), FALSE) THEN ((SELECT share_percent FROM delivery_disciplines WHERE delivery_discipline_id = p_delivery_discipline_id))::text ELSE (0)::text END)::numeric;
$$ LANGUAGE sql STABLE;

-- calc_delivery_disciplines_is_major_discipline
-- Field: DeliveryDisciplines.IsMajorDiscipline
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_delivery_disciplines_is_major_discipline(p_delivery_discipline_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (((SELECT share_percent FROM delivery_disciplines WHERE delivery_discipline_id = p_delivery_discipline_id))::NUMERIC >= 20)::boolean;
$$ LANGUAGE sql STABLE;

-- calc_delivery_disciplines_is_visible_major
-- Field: DeliveryDisciplines.IsVisibleMajor
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_delivery_disciplines_is_visible_major(p_delivery_discipline_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((COALESCE((SELECT client_visible FROM delivery_disciplines WHERE delivery_discipline_id = p_delivery_discipline_id), FALSE) AND calc_delivery_disciplines_is_major_discipline(p_delivery_discipline_id)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_delivery_disciplines_discipline_tier
-- Field: DeliveryDisciplines.DisciplineTier
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_delivery_disciplines_discipline_tier(p_delivery_discipline_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN calc_delivery_disciplines_is_visible_major(p_delivery_discipline_id) THEN ('major')::text ELSE (CASE WHEN COALESCE((SELECT client_visible FROM delivery_disciplines WHERE delivery_discipline_id = p_delivery_discipline_id), FALSE) THEN ('minor')::text ELSE ('internal')::text END)::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_delivery_disciplines_is_client_headline
-- Field: DeliveryDisciplines.IsClientHeadline
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_delivery_disciplines_is_client_headline(p_delivery_discipline_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (calc_delivery_disciplines_discipline_tier(p_delivery_discipline_id) = 'major')::boolean;
$$ LANGUAGE sql STABLE;

-- calc_delivery_disciplines_discipline_label
-- Field: DeliveryDisciplines.DisciplineLabel
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_delivery_disciplines_discipline_label(p_delivery_discipline_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN calc_delivery_disciplines_is_client_headline(p_delivery_discipline_id) THEN (CONCAT((SELECT NULLIF(title, '') FROM delivery_disciplines WHERE delivery_discipline_id = p_delivery_discipline_id), ' *'))::text ELSE ((SELECT NULLIF(title, '') FROM delivery_disciplines WHERE delivery_discipline_id = p_delivery_discipline_id))::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_erb_packages_phase_title
-- Field: ERBPackages.PhaseTitle
-- Type: lookup | DataType: string | Returns: TEXT
-- Lookup: Title from related BuildPhases


CREATE OR REPLACE FUNCTION calc_erb_packages_phase_title(p_erb_package_id TEXT)
RETURNS TEXT AS $$
  SELECT (SELECT title::text FROM build_phases WHERE build_phase_id = (SELECT primary_phase FROM erb_packages WHERE erb_package_id = p_erb_package_id));
$$ LANGUAGE sql STABLE;

-- calc_erb_packages_phase_number
-- Field: ERBPackages.PhaseNumber
-- Type: lookup | DataType: integer | Returns: INTEGER
-- Lookup: PhaseNumber from related BuildPhases


CREATE OR REPLACE FUNCTION calc_erb_packages_phase_number(p_erb_package_id TEXT)
RETURNS INTEGER AS $$
