-- get_acceptance_criteria_is_met
-- Helper function: Get IsMet from AcceptanceCriteria by AcceptanceCriterionId
-- Used for join-free cross-table references in aggregations

CREATE OR REPLACE FUNCTION get_acceptance_criteria_is_met(p_acceptance_criterion_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (SELECT is_met FROM acceptance_criteria WHERE acceptance_criterion_id = p_acceptance_criterion_id);
$$ LANGUAGE sql STABLE;

-- calc_user_stories_name
-- Field: UserStories.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_user_stories_name(p_user_story_id TEXT)
RETURNS TEXT AS $$
  SELECT ((SELECT NULLIF(req_id, '') FROM user_stories WHERE user_story_id = p_user_story_id))::text;
$$ LANGUAGE sql STABLE;

-- calc_user_stories_criterion_count
-- Field: UserStories.CriterionCount
-- Type: aggregation | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_user_stories_criterion_count(p_user_story_id TEXT)
RETURNS NUMERIC AS $$
  SELECT ((SELECT COUNT(*) FROM acceptance_criteria WHERE user_story = (SELECT NULLIF(user_story_id, '') FROM user_stories WHERE user_story_id = p_user_story_id)))::numeric;
$$ LANGUAGE sql STABLE;

-- calc_user_stories_is_done
-- Field: UserStories.IsDone
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_user_stories_is_done(p_user_story_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((SELECT NULLIF(status, '') FROM user_stories WHERE user_story_id = p_user_story_id) = 'done')::boolean;
$$ LANGUAGE sql STABLE;

-- calc_user_stories_done_flag
-- Field: UserStories.DoneFlag
-- Type: calculated | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_user_stories_done_flag(p_user_story_id TEXT)
RETURNS NUMERIC AS $$
  SELECT (CASE WHEN (SELECT NULLIF(status, '') FROM user_stories WHERE user_story_id = p_user_story_id) = 'done' THEN (1)::text ELSE (0)::text END)::numeric;
$$ LANGUAGE sql STABLE;

-- calc_user_stories_met_criterion_count
-- Field: UserStories.MetCriterionCount
-- Type: aggregation | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_user_stories_met_criterion_count(p_user_story_id TEXT)
RETURNS NUMERIC AS $$
  SELECT ((SELECT COALESCE(SUM((calc_acceptance_criteria_met_flag(acceptance_criterion_id))::numeric), 0) FROM acceptance_criteria WHERE user_story = p_user_story_id))::numeric;
$$ LANGUAGE sql STABLE;

-- calc_user_stories_has_criteria
-- Field: UserStories.HasCriteria
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_user_stories_has_criteria(p_user_story_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((calc_user_stories_criterion_count(p_user_story_id))::NUMERIC > 0)::boolean;
$$ LANGUAGE sql STABLE;

-- calc_user_stories_weighted_done
-- Field: UserStories.WeightedDone
-- Type: calculated | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_user_stories_weighted_done(p_user_story_id TEXT)
RETURNS NUMERIC AS $$
  SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_user_stories_done_flag(p_user_story_id)) AS v) __safe_numeric), 0) * COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_user_stories_effort_weight(p_user_story_id)) AS v) __safe_numeric), 0)))::numeric;
$$ LANGUAGE sql STABLE;

-- calc_user_stories_derived_progress_percent
-- Field: UserStories.DerivedProgressPercent
-- Type: calculated | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_user_stories_derived_progress_percent(p_user_story_id TEXT)
RETURNS NUMERIC AS $$
  SELECT (CASE WHEN calc_user_stories_has_criteria(p_user_story_id) THEN (ROUND(((COALESCE(100, 0) * COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_user_stories_met_criterion_count(p_user_story_id)) AS v) __safe_numeric), 0) / NULLIF(COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_user_stories_criterion_count(p_user_story_id)) AS v) __safe_numeric), 0), 0))) AS v) __safe_numeric), 0)))::NUMERIC, (0)::INTEGER))::text ELSE ((SELECT dev_progress_percent FROM user_stories WHERE user_story_id = p_user_story_id))::text END)::numeric;
$$ LANGUAGE sql STABLE;

-- calc_user_stories_is_acceptance_complete
-- Field: UserStories.IsAcceptanceComplete
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_user_stories_is_acceptance_complete(p_user_story_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((calc_user_stories_has_criteria(p_user_story_id) AND calc_user_stories_met_criterion_count(p_user_story_id) = calc_user_stories_criterion_count(p_user_story_id)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_user_stories_has_status_drift
-- Field: UserStories.HasStatusDrift
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_user_stories_has_status_drift(p_user_story_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((calc_user_stories_is_done(p_user_story_id) AND calc_user_stories_met_criterion_count(p_user_story_id) <> calc_user_stories_criterion_count(p_user_story_id)))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_user_stories_weighted_progress
-- Field: UserStories.WeightedProgress
-- Type: calculated | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_user_stories_weighted_progress(p_user_story_id TEXT)
RETURNS NUMERIC AS $$
  SELECT ((COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (calc_user_stories_derived_progress_percent(p_user_story_id)) AS v) __safe_numeric), 0) * COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT (COALESCE(calc_user_stories_effort_weight(p_user_story_id), 0)) AS v) __safe_numeric), 0)))::numeric;
$$ LANGUAGE sql STABLE;

-- calc_user_stories_progress_state
-- Field: UserStories.ProgressState
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_user_stories_progress_state(p_user_story_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN calc_user_stories_has_status_drift(p_user_story_id) THEN ('drift')::text ELSE (CASE WHEN calc_user_stories_is_acceptance_complete(p_user_story_id) THEN ('accepted')::text ELSE (CASE WHEN (calc_user_stories_derived_progress_percent(p_user_story_id))::NUMERIC > 0 THEN ('in-flight')::text ELSE ('not-started')::text END)::text END)::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_user_stories_priority_band
-- Field: UserStories.PriorityBand
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_user_stories_priority_band(p_user_story_id TEXT)
RETURNS TEXT AS $$
  WITH __erb_dedup_v1 AS (SELECT calc_user_stories_progress_state(p_user_story_id) AS val) SELECT (CASE WHEN (SELECT val FROM __erb_dedup_v1) = 'drift' THEN ('fix-first')::text ELSE (CASE WHEN (SELECT val FROM __erb_dedup_v1) = 'in-flight' THEN ('continue')::text ELSE ('queue')::text END)::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_user_stories_report_label
-- Field: UserStories.ReportLabel
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_user_stories_report_label(p_user_story_id TEXT)
RETURNS TEXT AS $$
  SELECT (CONCAT((SELECT NULLIF(req_id, '') FROM user_stories WHERE user_story_id = p_user_story_id), ' ', calc_user_stories_progress_state(p_user_story_id)))::text;
$$ LANGUAGE sql STABLE;

-- calc_acceptance_criteria_story_req_id
-- Field: AcceptanceCriteria.StoryReqId
-- Type: lookup | DataType: string | Returns: TEXT
-- Lookup: ReqId from related UserStories


CREATE OR REPLACE FUNCTION calc_acceptance_criteria_story_req_id(p_acceptance_criterion_id TEXT)
RETURNS TEXT AS $$
  SELECT (SELECT req_id::text FROM user_stories WHERE user_story_id = (SELECT user_story FROM acceptance_criteria WHERE acceptance_criterion_id = p_acceptance_criterion_id));
$$ LANGUAGE sql STABLE;

-- calc_acceptance_criteria_story_status
-- Field: AcceptanceCriteria.StoryStatus
-- Type: lookup | DataType: string | Returns: TEXT
-- Lookup: Status from related UserStories


CREATE OR REPLACE FUNCTION calc_acceptance_criteria_story_status(p_acceptance_criterion_id TEXT)
RETURNS TEXT AS $$
  SELECT (SELECT status::text FROM user_stories WHERE user_story_id = (SELECT user_story FROM acceptance_criteria WHERE acceptance_criterion_id = p_acceptance_criterion_id));
$$ LANGUAGE sql STABLE;

-- calc_acceptance_criteria_story_is_done
-- Field: AcceptanceCriteria.StoryIsDone
-- Type: lookup | DataType: boolean | Returns: BOOLEAN
-- Lookup: IsDone from related UserStories


CREATE OR REPLACE FUNCTION calc_acceptance_criteria_story_is_done(p_acceptance_criterion_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT calc_user_stories_is_done((SELECT user_story FROM acceptance_criteria WHERE acceptance_criterion_id = p_acceptance_criterion_id));
$$ LANGUAGE sql STABLE;

-- calc_acceptance_criteria_story_criterion_count
-- Field: AcceptanceCriteria.StoryCriterionCount
-- Type: lookup | DataType: number | Returns: NUMERIC
-- Lookup: CriterionCount from related UserStories


CREATE OR REPLACE FUNCTION calc_acceptance_criteria_story_criterion_count(p_acceptance_criterion_id TEXT)
RETURNS NUMERIC AS $$
  SELECT calc_user_stories_criterion_count((SELECT user_story FROM acceptance_criteria WHERE acceptance_criterion_id = p_acceptance_criterion_id));
$$ LANGUAGE sql STABLE;

-- calc_acceptance_criteria_story_derived_progress
-- Field: AcceptanceCriteria.StoryDerivedProgress
-- Type: lookup | DataType: number | Returns: NUMERIC
-- Lookup: DerivedProgressPercent from related UserStories


CREATE OR REPLACE FUNCTION calc_acceptance_criteria_story_derived_progress(p_acceptance_criterion_id TEXT)
RETURNS NUMERIC AS $$
  SELECT calc_user_stories_derived_progress_percent((SELECT user_story FROM acceptance_criteria WHERE acceptance_criterion_id = p_acceptance_criterion_id));
$$ LANGUAGE sql STABLE;

-- calc_acceptance_criteria_name
-- Field: AcceptanceCriteria.Name
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_acceptance_criteria_name(p_acceptance_criterion_id TEXT)
RETURNS TEXT AS $$
  SELECT ((SELECT NULLIF(acceptance_criterion_id, '') FROM acceptance_criteria WHERE acceptance_criterion_id = p_acceptance_criterion_id))::text;
$$ LANGUAGE sql STABLE;

-- calc_acceptance_criteria_met_flag
-- Field: AcceptanceCriteria.MetFlag
-- Type: calculated | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_acceptance_criteria_met_flag(p_acceptance_criterion_id TEXT)
RETURNS NUMERIC AS $$
  SELECT (CASE WHEN COALESCE((SELECT is_met FROM acceptance_criteria WHERE acceptance_criterion_id = p_acceptance_criterion_id), FALSE) THEN (1)::text ELSE (0)::text END)::numeric;
$$ LANGUAGE sql STABLE;

-- calc_acceptance_criteria_is_inconsistent_with_story
-- Field: AcceptanceCriteria.IsInconsistentWithStory
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_acceptance_criteria_is_inconsistent_with_story(p_acceptance_criterion_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (((COALESCE(calc_acceptance_criteria_story_is_done(p_acceptance_criterion_id), FALSE) = 'true') AND NOT (COALESCE((SELECT is_met FROM acceptance_criteria WHERE acceptance_criterion_id = p_acceptance_criterion_id), FALSE))))::boolean;
$$ LANGUAGE sql STABLE;

-- calc_acceptance_criteria_share_of_story
-- Field: AcceptanceCriteria.ShareOfStory
-- Type: calculated | DataType: number | Returns: NUMERIC


CREATE OR REPLACE FUNCTION calc_acceptance_criteria_share_of_story(p_acceptance_criterion_id TEXT)
RETURNS NUMERIC AS $$
  WITH __erb_dedup_v1 AS (SELECT calc_acceptance_criteria_story_criterion_count(p_acceptance_criterion_id) AS val) SELECT (CASE WHEN (COALESCE((SELECT val FROM __erb_dedup_v1), 0))::NUMERIC = 0 THEN (0)::text ELSE (ROUND(((COALESCE(100, 0) / NULLIF(COALESCE((SELECT CASE WHEN v::text ~ '^-?[0-9]*\.?[0-9]+$' THEN v::numeric ELSE NULL END FROM (SELECT ((SELECT val FROM __erb_dedup_v1)) AS v) __safe_numeric), 0), 0)))::NUMERIC, (0)::INTEGER))::text END)::numeric;
$$ LANGUAGE sql STABLE;

-- calc_acceptance_criteria_criterion_state
-- Field: AcceptanceCriteria.CriterionState
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_acceptance_criteria_criterion_state(p_acceptance_criterion_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN calc_acceptance_criteria_is_inconsistent_with_story(p_acceptance_criterion_id) THEN ('contradicts-story')::text ELSE (CASE WHEN COALESCE((SELECT is_met FROM acceptance_criteria WHERE acceptance_criterion_id = p_acceptance_criterion_id), FALSE) THEN ('met')::text ELSE ('pending')::text END)::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_acceptance_criteria_needs_review
-- Field: AcceptanceCriteria.NeedsReview
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_acceptance_criteria_needs_review(p_acceptance_criterion_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (calc_acceptance_criteria_criterion_state(p_acceptance_criterion_id) = 'contradicts-story')::boolean;
$$ LANGUAGE sql STABLE;

-- calc_acceptance_criteria_story_is_ahead_of_criterion
-- Field: AcceptanceCriteria.StoryIsAheadOfCriterion
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_acceptance_criteria_story_is_ahead_of_criterion(p_acceptance_criterion_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((NOT (COALESCE((SELECT is_met FROM acceptance_criteria WHERE acceptance_criterion_id = p_acceptance_criterion_id), FALSE)) AND (COALESCE(calc_acceptance_criteria_story_derived_progress(p_acceptance_criterion_id), 0))::NUMERIC >= 50));
$$ LANGUAGE sql STABLE;

-- calc_consistency_rules_name
