-- calc_consistency_findings_domain_finding_count
-- Field: ConsistencyFindings.DomainFindingCount
-- Type: lookup | DataType: number | Returns: NUMERIC
-- Lookup: FindingCount from related RulebookDomains


CREATE OR REPLACE FUNCTION calc_consistency_findings_domain_finding_count(p_consistency_finding_id TEXT)
