-- calc_consistency_findings_rule_finding_count
-- Field: ConsistencyFindings.RuleFindingCount
-- Type: lookup | DataType: number | Returns: NUMERIC
-- Lookup: FindingCount from related ConsistencyRules


CREATE OR REPLACE FUNCTION calc_consistency_findings_rule_finding_count(p_consistency_finding_id TEXT)
