-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_consistency_findings_is_sole_blocker(p_consistency_finding_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((calc_consistency_findings_is_open(p_consistency_finding_id) AND (COALESCE(calc_consistency_findings_domain_open_finding_count(p_consistency_finding_id), 0))::NUMERIC = 1));
$$ LANGUAGE sql STABLE;

-- calc_consistency_findings_priority
-- Field: ConsistencyFindings.Priority
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_consistency_findings_priority(p_consistency_finding_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN calc_consistency_findings_is_open_critical(p_consistency_finding_id) THEN ('P1')::text ELSE (CASE WHEN calc_consistency_findings_is_sole_blocker(p_consistency_finding_id) THEN ('P2')::text ELSE (CASE WHEN calc_consistency_findings_is_open(p_consistency_finding_id) THEN ('P3')::text ELSE ('closed')::text END)::text END)::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_consistency_findings_is_last_mile
