  SELECT ((calc_consistency_findings_is_sole_blocker(p_consistency_finding_id) AND COALESCE(calc_consistency_findings_domain_grade(p_consistency_finding_id), '') = 'minor'))::boolean;
$$ LANGUAGE sql STABLE;

