  SELECT (CONCAT((SELECT NULLIF(title, '') FROM project_layout_slots WHERE project_layout_slot_id = p_project_layout_slot_id), ' [', calc_project_layout_slots_slot_health(p_project_layout_slot_id), ']'))::text;
$$ LANGUAGE sql STABLE;

