  SELECT (LENGTH((SELECT NULLIF(description, '') FROM project_goal WHERE project_goal_id = p_project_goal_id)))::integer;
$$ LANGUAGE sql STABLE;

-- calc_project_goal_is_substantive
-- Field: ProjectGoal.IsSubstantive
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_project_goal_is_substantive(p_project_goal_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT ((calc_project_goal_description_length(p_project_goal_id))::NUMERIC >= 200)::boolean;
$$ LANGUAGE sql STABLE;

-- calc_project_goal_narrative_state
-- Field: ProjectGoal.NarrativeState
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_project_goal_narrative_state(p_project_goal_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN calc_project_goal_is_substantive(p_project_goal_id) THEN ('ready')::text ELSE ('stub')::text END)::text;
$$ LANGUAGE sql STABLE;

-- calc_project_goal_is_ready
-- Field: ProjectGoal.IsReady
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_project_goal_is_ready(p_project_goal_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (calc_project_goal_narrative_state(p_project_goal_id) = 'ready')::boolean;
$$ LANGUAGE sql STABLE;

-- calc_project_goal_section_label
-- Field: ProjectGoal.SectionLabel
-- Type: calculated | DataType: string | Returns: TEXT


CREATE OR REPLACE FUNCTION calc_project_goal_section_label(p_project_goal_id TEXT)
RETURNS TEXT AS $$
  SELECT (CASE WHEN calc_project_goal_is_ready(p_project_goal_id) THEN (CONCAT((SELECT NULLIF(name, '') FROM project_goal WHERE project_goal_id = p_project_goal_id), ' (ready)'))::text ELSE (CONCAT((SELECT NULLIF(name, '') FROM project_goal WHERE project_goal_id = p_project_goal_id), ' (stub)'))::text END)::text;
$$ LANGUAGE sql STABLE;

