-- Field: ExecutionSubstrates.IsCataloged
-- Type: calculated | DataType: boolean | Returns: BOOLEAN


CREATE OR REPLACE FUNCTION calc_execution_substrates_is_cataloged(p_substrate_id TEXT)
RETURNS BOOLEAN AS $$
